def order(check, handoff):
    if check is None or handoff is None:
        return "missing record"
    if check == handoff:
        return "order unknown"
    return "in order" if check < handoff else "reversed"

for pair in [(None, 6), (6, 6), (7, 6)]:
    print(order(*pair))

def model_a(busy, extra):
    return 4 + 6 * busy - 2 * extra

def model_b(busy, extra):
    return 4 + 4 * busy

for busy, extra in [(0, 0), (1, 1), (1, 0)]:
    print(model_a(busy, extra), model_b(busy, extra))

